/* @socom-skeleton body ClearAnims__8CZWeaponFv */
void CZWeapon::ClearAnims()
{
	if (m_hitanim != NULL)
	{
		zfree(m_hitanim);
		m_hitanim = NULL;
	}

	m_fireanim = NULL;
	m_zoomedfireanim = NULL;
	m_defaultspecialanim = NULL;
	
	if (m_specialmaterialanim != NULL)
	{
		zfree(m_specialmaterialanim);
		m_specialmaterialanim = NULL;
	}
}

